r-color:#bb756454}.action-button:disabled{opacity:.38;cursor:not-allowed;transform:none}.new-game{border:0;background:transparent;color:#aaa79d;display:flex;align-items:center;gap:7px;font:10px var(--mono);cursor:pointer}.new-game:hover{color:var(--gold)}.bottom-bar{height:31px;border-top:1px solid #ffffff12;display:flex;justify-content:space-between;align-items:flex-end;color:#85847d;font-size:10px}.bottom-bar>span{display:flex;align-items:center;gap:9px}.key-hint{padding:3px 5px;border:1px solid #ffffff2c;border-radius:3px;color:#d4be8a;font:8px var(--mono);letter-spacing:.7px}.modal-backdrop{position:fixed;inset:0;background:#000a;z-index:20;display:grid;place-items:center;padding:18px;backdrop-filter:blur(5px)}.modal-backdrop[hidden]{display:none}.rules-modal{width:min(465px,100%);position:relative;padding:33px 36px 25px;border:1px solid #ffffff1b;border-radius:13px;background:#242522;box-shadow:0 24px 80px #0009}.modal-close{position:absolute;right:15px;top:12px;background:none;border:0;color:#9b998f;font-size:25px;cursor:pointer}.modal-eyebrow{font:9px var(--mono);letter-spacing:1.5px;color:#d4b674}.rules-modal h2{margin:8px 0 19px;font:700 28px/1.17 var(--serif);color:#f4eee1}.rules-modal h2 em{color:#d8b576}.rules-tabs{display:flex;gap:17px;border-bottom:1px solid #ffffff1b}.rules-tabs button{border:0;background:none;color:#96958c;padding:0 0 10px;font:10px var(--mono);cursor:pointer}.rules-tabs button.active{color:#ecd097;border-bottom:2px solid #dfb86c}.rules-content{min-height:166px;padding:15px 0 7px;color:#c1bfb5;font-size:12px;line-height:1.65}.rules-content ul{padding-left:17px;margin:6px 0}.rules-content li{padding:3px 0}.rules-content strong{color:#f1ddae;font-weight:600}..learn-toggle{border-top:1px solid #ffffff17;padding-top:16px;display:flex;align-items:center;gap:10px;color:#e1ded4;font-size:11px;cursor:pointer}.learn-toggle input{position:absolute;opacity:0}.toggle-ui{width:32px;height:18px;border-radius:12px;background:#50504a;position:relative;transition:.2s}.toggle-ui:after{content:"";position:absolute;top:3px;left:3px;width:12px;height:12px;border-radius:50%;background:#d8d5ca;transition:.2s}.learn-toggle input:checked+.toggle-ui{background:#7d9a6e}.learn-toggle input:checked+.toggle-ui:after{left:17px;background:#fff}.learn-toggle small{display:block;color:#88877f;font-size:9px;margin-top:3px}.toast{position:fixed;left:50%;bottom:26px;transform:translate(-50%,20px);padding:10px 15px;border:1px solid #ffffff20;border-radius:7px;background:#272824;color:#f0d7a2;font:11px var(--mono);opacity:0;pointer-events:none;transition:.25s;z-index:40}.toast.show{opacity:1;transform:translate(-50%,0)}.meld-badge{position:absolute;left:50%;top:-23px;transform:translateX(-50%);padding:4px 7px;border-radius:10px;background:#ead293;color:#392d19;font:700 8px var(--mono);white-space:nowrap}.hand .card.trump:after{content:"";position:absolute;top:3px;right:3px;width:4px;height:4px;border-radius:50%;background:#d2a953}.card.selected{outline:2px solid #e8c981;outline-offset:2px}
