  }
  function showControls() {
    const controls = $('controls');
    if (state.phase === 'bidding' && state.bidOrder[state.bidIndex] === 0) {
      controls.innerHTML = '<button class="action-button primary" data-action="accept">♠ &nbsp; ABNEHMEN</button><button class="action-button" data-action="pass">WEG &nbsp; ↗</button>';
    } else if (state.phase === 'counter' && state.counterPlayer === 0) {
      controls.innerHTML = '<button class="action-button primary" data-action="schuss">⚡ &nbsp; SCHUSS</button><button class="action-button" data-action="counter-pass">NO THANKS</button>';
    } else if (state.phase === 'forced' && state.dealer === 0) {
      controls.innerHTML = SUITS.map(s => `<button class="action-button suit-choice" data-suit="${s.id}"><span class="${s.color}">${s.symbol}</span> ${s.name.toUpperCase()}</button>`).join('') + '<button class="action-button" data-action="gift" title="Let the opposing team choose a side suit; they score 50 points">SCHENKEN · +50</button>';
    } else if (state.phase === 'play' && state.turn === 0 && !state.busy) {
      controls.innerHTML = '<span class="play-hint">↑ &nbsp; TAP A CARD TO PLAY</span>';
    } else if (state.phase === 'roundEnd') {
      controls.innerHTML = `<button class="action-button primary" data-action="next-round">${state.scores.some(s => s >= 1000) ? 'PLAY AGAIN' : 'NEXT HAND'} &nbsp; →</button>`;
    } else if (state.phase === 'play') {
      controls.innerHTML = `<span class="play-hint">${state.turn === 0 ? 'Choose a legal card' : 'The table is playing…'}</span>`;
    } else controls.innerHTML = '<span class="play-hint">Waiting for the table…</span>';
  }
  function update() {
    $('usScore').textContent = state.scores[0]; $('themScore').textContent = state.scores[1];
    $('usTricks').textContent = `${state.tricks[0]} trick${state.tricks[0] === 1 ? '' : 's'}`;
    $('themTricks').textContent = `${state.tricks[1]} trick${state.tricks[1] === 1 ? '' : 's'}`;
    $('roundLabel').textContent = `ROUND ${String(state.round).padStart(2, '0')}`;
    $('phaseLabel').textContent = state.phase === 'play' ? `TRICK ${Math.min(state.trickNo + 1, 8)} / 8` : state.phase === 'roundEnd' ? 'HAND COMPLETE' : state.phase === 'forced' ? 'LETZTER MUSS' : state.phase === 'counter' ? 'COUNTER BID' : 'BIDDING';
    $('yourTurn').classList.toggle('active', (state.phase === 'play' && state.turn === 0) || (state.phase === 'bidding' && state.bidOrder[state.bidIndex] === 0) || (state.phase === 'forced' && state.dealer === 0) || (state.phase === 'counter' && state.counterPlayer === 0));
    renderSeats(); renderHand(); renderTrick(); showControls();
  }
  function toast(text) {
    const el = $('toast'); el.textContent = text; el.classList.add('show');
    clearTimeout(toast.timer); toast.timer = setTimeout(() => el.classList.remove('show'), 2600);
  }
  function playSound() {
    if (!state.sound) return;
    try {
      const context = new (window.AudioContext || window.webkitAudioContext)();
      const osc = context.createOscillator(), gain = context.createGain();
      osc.type = 'triangle'; osc.frequency.value = 340; gain.gain.setValueAtTime(.035, context.currentTime); gain.gain.exponentialRampToValueAtTime(.001, context.currentTime + .07);
      osc.connect(gain); gain.connect(context.destination); osc.start(); osc.stop(context.currentTime + .08); osc.onended = () => context.close();
    } catch (_) { /* Audio is optional. */ }
  }
  function resetGame() {
    state.round = 1; state.scores = [0, 0]; state.tricks = [0, 0]; state.dealer = Math.floor(Math.random() * 4);
    toast('Fresh deck. Good luck!'); deal();
  }
  function handleAction(action) {
    if (action === 'accept') acceptBid(0);
    if (action === 'pass') passBid(0);
    if (action === 'schuss') applySchuss(0);
    if (action === 'counter-pass') startPlay();
    if (action === 'gift') { state.pendingGift = true; toast('Choose a suit to gift to the dealer for 50 points'); }
    if (action === 'next-round') {
      if (state.scores.some(s => s >= 1000)) resetGame();
      else { state.round++; state.dealer = (state.dealer + 1) % 4; deal(); }
    }
  }
  $('controls').addEventListener('click', (event) => {
    const button = event.target.closest('button'); if (!button) return;
    if (button.dataset.action) handleAction(button.dataset.action);
    if (button.dataset.suit) {
      const suit = button.dataset.suit;
      if (state.pendingGift) { state.roundPoints[1] += 50; state.pendingGift = false; toast(`Schenken! Opponents score 50 · ${suitById(suit).name} is trump`); }
      state.trump = suit; state.bidSuit = suit; state.acceptor = state.dealer; startPlay();
    }
  });
  $('playerHand').addEventListener('click', (event) => {
    const el = event.target.closest('[data-card]'); if (!el || el.classList.contains('illegal')) return;
    const card = state.hands[0].find(c => c.id === el.dataset.card); if (card) playCard(0, card);
  });
  $('playerHand').addEventListener('keydown', (event) => {
    if (event.key !== 'Enter' && event.key !== ' ') return;
    const el = event.target.closest('[data-card]'); if (!el || el.classList.contains('illegal')) return;
    event.preventDefault(); const card = state.hands[0].find(c => c.id === el.dataset.card); if (card) playCard(0, card);
  });
  $('newGameButton').addEventListener('click', resetGame);
  $('designButton').addEventListener('click', () => { state.design = state.design % 3 + 1; update(); toast(`Card design ${state.design} of 3`); });
  $('soundButton').addEventListener('click', () => { state.sound = !state.sound; $('soundButton').classList.toggle('sound-off', !state.sound); toast(state.sound ? 'Sound on' : 'Sound off'); });
  const modal = $('modalBackdrop');
  $('rulesButton').addEventListener('click', () => { modal.hidden = false; document.body.style.overflow = 'hidden'; });
  $('closeModal').addEventListener('click', () => { modal.hidden = true; document.body.style.overflow = ''; });
  modal.addEventListener('click', e => { if (e.target === modal) { modal.hidden = true; document.body.style.overflow = ''; } });
  document.addEventListener('keydown', e => { if (e.key === 'Escape') { modal.hidden = true; document.body.style.overflow = ''; } });
  document.querySelectorAll('.rules-tabs button').forEach(button => button.addEventListener('click', () => {
    document.querySelectorAll('.rules-tabs button').forEach(b => b.classList.toggle('active', b === button));
    $('rulesContent').innerHTML = rules[button.dataset.tab];
  }));
  $('rulesContent').innerHTML = rules.play;
  $('learnToggle').addEventListener('change', e => { state.learn = e.target.checked; toast(state.learn ? 'Learn mode is on — hints will appear as you play' : 'Learn mode is off'); });
  deal();
})();

